class Solution {
  private int bestDiff;
  private int[] best, path;
  private int k;

  private void dfs(int pos, int remaining, int minFactor) {
    if (pos == k - 1) {
      if (remaining >= minFactor) {
        path[pos] = remaining;
        int diff = path[k - 1] - path[0];
        if (diff < bestDiff) {
          bestDiff = diff;
          best = path.clone();
        }
      }
      return;
    }
    for (int f = minFactor; ; f++) {
      long power = 1;
      for (int t = 0; t < k - pos && power <= remaining; t++) power *= f;
      if (power > remaining) break;
      if (remaining % f != 0) continue;
      path[pos] = f;
      dfs(pos + 1, remaining / f, f);
    }
  }

  public int[] minDifference(int n, int k) {
    this.k = k;
    bestDiff = Integer.MAX_VALUE;
    path = new int[k];
    dfs(0, n, 1);
    return best;
  }
}
